input.content:
@import './fonts.css';

:root {
  --paper: #f4eddd;
  --paper-2: #e9dfca;
  --paper-3: #ddd0b5;
  --ink: #232019;
  --ink-soft: #4c4438;
  --ink-faint: #7b6f5c;
  --verm: #b33a2b;
  --verm-bright: #d4553f;
  --gold: #b6914f;
  --gold-soft: #d8c393;
  --moss: #5c7254;
  --night: #12100e;
  --line: rgba(60, 46, 30, 0.22);
  --serif: 'Cormorant Garamond', 'Shippori Mincho', Georgia, serif;
  --jp: 'Shippori Mincho', 'Cormorant Garamond', serif;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.5);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; height: 100%; overflow: hidden;
  background: #0d0c0a; color: var(--ink);
  font-family: var(--serif);
  font-size: 16px;
  overscroll-behavior: none;
  user-select: none;
}

body { touch-action: none; }
button { font-family: inherit; cursor: pointer; }
canvas#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

#app { position: fixed; inset: 0; }

.vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 1;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(15, 11, 7, 0.35) 100%);
  mix-blend-mode: multiply;
}
.grain {
  position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.12;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.35'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

.hidden { display: none !important; }

/* ————— HUD ————— */
#hud {
  position: fixed; top: 0; left: 0; right: 0; z-index: 30;
  display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
  padding: 18px 22px;
  padding-top: max(18px, env(safe-area-inset-top));
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(14, 12, 9, 0.62), transparent);
}
#hud > * { pointer-events: auto; }
.brand { display: flex; align-items: center; gap: 11px; color: var(--paper); }
.crest {
  display: grid; place-items: center; width: 46px; height: 46px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #cf4d39, #982d23 70%);
  color: #f8efdf; font-family: var(--jp); font-size: 26px;
  border: 1px solid rgba(255, 235, 200, 0.4);
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.45), inset 0 0 10px rgba(0,0,0,.25);
}
.brand-text { display: flex; flex-direction: column; line-height: 1; text-shadow: 0 2px 8px rgba(0,0,0,.6); }
.brand-text span { font-size: 9px; letter-spacing: 0.42em; color: #d5c5a8; margin-bottom: 4px; }
.brand-text strong { font-size: 18px; font-weight: 600; letter-spacing: 0.16em; }

.stats { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; }
.stat {
  display: flex; align-items: center; gap: 9px;
  background: linear-gradient(160deg, rgba(28, 24, 19, 0.82), rgba(18, 15, 12, 0.75));
  border: 1px solid rgba(216, 195, 147, 0.24);
  border-radius: 3px; padding: 7px 13px 7px 9px; min-width: 104px;
  color: var(--paper); backdrop-filter: blur(8px);
  box-shadow: 0 4px 20px rgba(0,0,0,.25);
}
.stat-k {
  font-family: var(--jp); font-size: 20px; color: var(--gold-soft);
  width: 28px; height: 28px; display: grid; place-items: center;
  border: 1px solid rgba(216,195,147,.25); border-radius: 50%;
}
.stat > div { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.stat small { font-size: 8px; letter-spacing: .2em; color: #a99a80; white-space: nowrap; }
.stat b { font-size: 15px; font-weight: 500; letter-spacing: .04em; white-space: nowrap; font-variant-numeric: tabular-nums; }
.stat.money b { color: #f1d9a0; font-size: 17px; }
.stat.rep i { display: block; width: 100%; height: 2px; background: rgba(255,255,255,.13); margin-top: 3px; border-radius: 2px; overflow: hidden; }
.stat.rep u { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #b6914f, #e7cf9a); transition: width .6s ease; }
.stat.date b { font-size: 13px; }
.stat.weather b { font-size: 12px; }
.stat.weather .stat-k { font-size: 17px; }

.hud-actions { display: flex; gap: 5px; }
.icon-btn {
  width: 46px; height: 46px; border-radius: 3px; padding: 2px 0 4px;
  background: linear-gradient(160deg, rgba(28,24,19,.84), rgba(18,15,12,.78));
  border: 1px solid rgba(216,195,147,.22); color: var(--paper);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  font-family: var(--jp); font-size: 15px; transition: .2s;
}
.icon-btn small { font-family: var(--serif); font-size: 6.5px; letter-spacing: .14em; color: #a99a80; }
.icon-btn:hover { background: rgba(179, 58, 43, .72); border-color: rgba(255, 220, 180, .4); transform: translateY(-1px); }

/* ————— quests ————— */
#quests {
  position: fixed; left: 22px; top: 94px; z-index: 25; width: 232px;
  background: linear-gradient(150deg, rgba(240,232,215,.94), rgba(226,214,190,.9));
  border: 1px solid rgba(80,60,35,.35); padding: 10px 12px 11px;
  box-shadow: 0 10px 40px rgba(0,0,0,.35), inset 0 0 0 3px rgba(255,250,235,.35);
  backdrop-filter: blur(5px);
}
.quest-head { display: flex; align-items: center; gap: 7px; padding-bottom: 7px; border-bottom: 1px solid rgba(80,60,35,.22); margin-bottom: 7px; }
.quest-head span { font-family: var(--jp); width: 20px; height: 20px; background: var(--verm); color: #f6ead6; display: grid; place-items: center; font-size: 11px; border-radius: 2px; }
.quest-head b { font-size: 9px; letter-spacing: .22em; font-weight: 600; color: var(--ink-soft); }
.quest { display: flex; gap: 7px; align-items: flex-start; padding: 4px 0; font-size: 12.5px; line-height: 1.25; color: var(--ink-soft); }
.quest .qmark { flex: 0 0 auto; width: 11px; height: 11px; margin-top: 2px; border: 1px solid rgba(80,60,35,.45); display: grid; place-items: center; font-size: 8px; }
.quest.done { color: #8b8577; text-decoration: line-through; }
.quest.done .qmark { background: var(--moss); color: #fff; border-color: var(--moss); }
.quest .qr { margin-left: auto; color: var(--gold); font-size: 10px; white-space: nowrap; }

/* ————— focus ————— */
#focus-wrap { position: fixed; left: 22px; bottom: 108px; z-index: 25; width: 178px; }
.focus-label { display: flex; align-items: center; gap: 6px; color: #e8ddc8; font-size: 10px; text-shadow: 0 1px 5px #000; letter-spacing: .12em; margin-bottom: 4px; }
.focus-label span { font-family: var(--jp); font-size: 14px; color: #d8c393; }
.focus-label b { margin-left: auto; font-weight: 500; font-variant-numeric: tabular-nums; }
.focus-bar { height: 4px; background: rgba(0,0,0,.45); border: 1px solid rgba(255,240,210,.18); overflow: hidden; }
.focus-bar u { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #7d9a6f, #cfe0b0); transition: width .4s; }

/* ————— zone / prompt ————— */
.zone-tag {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 20;
  color: #f5edda; font-family: var(--jp); font-size: 30px; letter-spacing: .35em;
  text-shadow: 0 2px 30px rgba(0,0,0,.8), 0 0 4px rgba(0,0,0,.6);
  opacity: 0; transition: opacity 1s; pointer-events: none; text-align: center;
}
.zone-tag.show { opacity: 1; animation: zonefade 3.6s forwards; }
.zone-tag small { display: block; font-family: var(--serif); font-size: 12px; letter-spacing: .5em; color: #d8c393; margin-top: 6px; }
@keyframes zonefade { 0% { opacity: 0; } 15% { opacity: 1; } 70% { opacity: 1; } 100% { opacity: 0; } }

.prompt {
  position: fixed; left: 50%; bottom: 130px; transform: translateX(-50%); z-index: 26;
  display: flex; align-items: center; gap: 9px; padding: 8px 16px 8px 8px;
  background: rgba(20, 17, 13, .86); border: 1px solid rgba(216,195,147,.35);
  color: var(--paper); font-size: 13px; letter-spacing: .06em; border-radius: 2px;
  box-shadow: 0 8px 30px rgba(0,0,0,.4); backdrop-filter: blur(6px);
}
.prompt kbd {
  font-family: var(--serif); font-size: 12px; background: var(--paper); color: var(--ink);
  width: 23px; height: 23px; display: grid; place-items: center; border-radius: 2px; box-shadow: 0 2px 0 #a49476;
}
.mobile-interact {
  position: fixed; right: 22px; bottom: 150px; z-index: 27;
  width: 76px; height: 76px; border-radius: 50%; border: 1px solid rgba(216,195,147,.6);
  background: radial-gradient(circle at 35% 30%, #c44837, #8e2c22);
  color: #f8efdf; font-family: var(--jp); font-size: 15px; letter-spacing: .08em;
  box-shadow: 0 6px 30px rgba(0,0,0,.5); display: grid; place-items: center;
}
.mobile-interact::after { content: ''; position: absolute; inset: -5px; border-radius: 50%; border: 1px solid rgba(216,195,147,.25); }

/* ————— dock ————— */
#dock {
  position: fixed; left: 50%; bottom: max(16px, env(safe-area-inset-bottom)); transform: translateX(-50%);
  z-index: 30; display: flex; gap: 2px; padding: 5px;
  background: linear-gradient(180deg, rgba(27,23,18,.94), rgba(16,13,10,.94));
  border: 1px solid rgba(216,195,147,.26);
  box-shadow: 0 15px 50px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,245,220,.08);
  border-radius: 3px; backdrop-filter: blur(10px);
}
#dock button {
  position: relative; width: 84px; padding: 8px 4px 7px; border: 0; background: transparent;
  color: #cdbfa7; display: flex; flex-direction: column; align-items: center; gap: 2px;
  border-radius: 2px; transition: .18s;
}
#dock button span {
  font-family: var(--jp); font-size: 21px; line-height: 1; color: #e7d8bd;
  width: 32px; height: 32px; display: grid; place-items: center; border-radius: 50%;
  transition: .2s;
}
#dock button b { font-size: 8.5px; letter-spacing: .16em; font-weight: 600; }
#dock button small { font-size: 8px; letter-spacing: .06em; color: #817563; font-style: italic; }
#dock button:hover { background: rgba(255,255,255,.05); color: #f3e8d2; }
#dock button:hover span { color: #fff; background: rgba(179,58,43,.45); }
#dock button.active { background: rgba(179,58,43,.2); color: #f6ead6; }
#dock button.active span { background: var(--verm); color: #fff7e8; box-shadow: 0 0 18px rgba(179,58,43,.5); }
#dock button .badge {
  position: absolute; top: 3px; right: 13px; background: var(--gold); color: #241c10;
  font-size: 7px; font-weight: 700; letter-spacing: .04em; padding: 1px 4px; border-radius: 8px;
  font-family: var(--serif);
}

/* ————— toasts ————— */
#toasts { position: fixed; right: 22px; top: 96px; z-index: 60; display: flex; flex-direction: column; gap: 7px; align-items: flex-end; pointer-events: none; max-width: 340px; }
.toast {
  background: linear-gradient(135deg, rgba(242,233,215,.97), rgba(228,216,192,.96));
  border: 1px solid rgba(80,60,35,.35); border-left: 3px solid var(--gold);
  padding: 9px 14px; font-size: 13px; color: var(--ink); box-shadow: 0 10px 30px rgba(0,0,0,.4);
  animation: toastin .35s ease; display: flex; gap: 8px; align-items: center;
}
.toast.good { border-left-color: var(--moss); }
.toast.warn { border-left-color: var(--verm); }
.toast .t-icon { font-family: var(--jp); color: var(--verm); font-size: 15px; }
.toast.out { opacity: 0; transform: translateX(20px); transition: .4s; }
@keyframes toastin { from { opacity: 0; transform: translateX(24px); } }

/* ————— compass ————— */
.compass {
  position: fixed; right: 22px; bottom: 112px; z-index: 25; width: 74px; text-align: center;
  color: #ebdfc9; font-size: 8px; letter-spacing: .18em; text-shadow: 0 1px 6px #000;
}
.compass .needle {
  width: 42px; height: 42px; margin: 0 auto 5px; border: 1px solid rgba(216,195,147,.35);
  border-radius: 50%; display: grid; place-items: center; font-family: var(--jp); font-size: 17px;
  background: rgba(20,17,13,.55); backdrop-filter: blur(4px);
}
#compass-label { color: #d8c393; }

/* ————— joystick ————— */
.joystick {
  position: fixed; left: 20px; bottom: 150px; z-index: 28; width: 106px; height: 106px; border-radius: 50%;
  border: 1px solid rgba(216,195,147,.3); background: rgba(18,15,12,.28); backdrop-filter: blur(4px);
  touch-action: none;
}
.joystick .stick {
  position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; border-radius: 50%;
  transform: translate(-50%, -50%); background: rgba(239,229,210,.3);
  border: 1px solid rgba(255,245,225,.5); box-shadow: 0 2px 12px rgba(0,0,0,.3);
}

/* ————— fade ————— */
.fade { position: fixed; inset: 0; background: #0b0907; opacity: 0; pointer-events: none; transition: opacity .55s; z-index: 70; }
.fade.show { opacity: 1; }

/* ————— intro ————— */
.intro { position: fixed; inset: 0; z-index: 90; background: #100d0a; color: var(--paper); display: grid; place-items: center; overflow: hidden; transition: opacity 1s; }
.intro.gone { opacity: 0; pointer-events: none; }
.intro-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 62% 38%, rgba(201, 128, 91, .22), transparent 55%),
    radial-gradient(ellipse at 20% 90%, rgba(42, 61, 43, .45), transparent 60%),
    linear-gradient(135deg, #0e0c0a 0%, #1c1510 55%, #2a1a14 100%);
}
.intro-bg::after {
  content: ''; position: absolute; inset: 0; opacity: .2;
  background-image: repeating-linear-gradient(115deg, transparent 0 40px, rgba(220,200,160,.11) 40px 41px);
}
.intro-vignette { position: absolute; inset: 0; box-shadow: inset 0 0 200px 60px #000; }
.intro-content { position: relative; z-index: 2; text-align: center; max-width: 760px; padding: 28px; animation: introin 1.4s ease; }
@keyframes introin { from { opacity: 0; transform: translateY(18px); } }
.intro-kanji { font-family: var(--jp); font-size: 15px; letter-spacing: .8em; color: var(--gold-soft); margin-bottom: 18px; opacity: .85; }
.intro-kicker { font-size: 11px; letter-spacing: .38em; color: #b7a68a; text-transform: uppercase; margin: 0 0 12px; }
.intro h1 { font-size: clamp(44px, 8vw, 88px); line-height: .88; margin: 0; font-weight: 500; letter-spacing: .07em; text-shadow: 0 4px 40px rgba(0,0,0,.6); }
.intro h1 em { font-style: italic; font-weight: 400; color: #e1c48d; letter-spacing: .03em; font-size: .82em; }
.intro-rule { display: flex; align-items: center; justify-content: center; gap: 16px; margin: 24px auto 20px; width: 70%; }
.intro-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(216,195,147,.55), transparent); }
.intro-rule i { font-family: var(--jp); font-style: normal; font-size: 17px; color: var(--verm-bright); width: 38px; height: 38px; border: 1px solid rgba(216,195,147,.4); display: grid; place-items: center; border-radius: 50%; }
.intro-copy { font-size: 16px; line-height: 1.7; color: #c8b99f; margin: 0 auto 30px; max-width: 600px; font-weight: 400; }
.intro-foot { display: flex; gap: 18px; justify-content: center; flex-wrap: wrap; margin-top: 30px; font-size: 10px; letter-spacing: .14em; color: #8d7f6a; text-transform: uppercase; }
.intro-foot span::before { content: '·'; margin-right: 8px; color: var(--gold); }
.intro-side {
  position: absolute; right: 34px; top: 50%; transform: translateY(-50%); writing-mode: vertical-rl;
  font-family: var(--jp); font-size: 14px; letter-spacing: .5em; color: rgba(216,195,147,.36);
}

.btn {
  border: 1px solid rgba(40,30,18,.4); background: linear-gradient(180deg, #f4ecda, #e3d6bc);
  color: var(--ink); padding: 9px 20px; font-size: 13px; letter-spacing: .1em; border-radius: 2px;
  transition: .18s; position: relative; box-shadow: 0 2px 0 rgba(120,98,64,.35);
}
.btn:hover { background: #fff8e8; transform: translateY(-1px); box-shadow: 0 4px 0 rgba(120,98,64,.25); }
.btn:active { transform: translateY(1px); box-shadow: 0 0 0 rgba(0,0,0,0); }
.btn-primary { background: linear-gradient(180deg, #c54a37, #9c3023); border-color: #7c241a; color: #fbf2df; box-shadow: 0 2px 0 #6d1f17; }
.btn-primary:hover { background: linear-gradient(180deg, #d85a45, #b13a2a); }
.btn-gold { background: linear-gradient(180deg, #d9bc7e, #b6904b); border-color: #8c6c33; color: #241c10; }
.btn-ghost { background: transparent; border-color: var(--line); box-shadow: none; color: var(--ink-soft); }
.btn-ghost:hover { background: rgba(0,0,0,.05); }
.btn:disabled { opacity: .38; cursor: not-allowed; transform: none !important; box-shadow: none; }
.btn-large { padding: 14px 44px; font-size: 15px; letter-spacing: .22em; background: linear-gradient(180deg, #c64b37, #98301f); color: #fff5e2; border: 1px solid rgba(255,220,170,.28); box-shadow: 0 10px 40px rgba(150,45,30,.4), 0 2px 0 #6a1e14; }
.btn-large:hover { background: linear-gradient(180deg, #db5b44, #ad3725); box-shadow: 0 12px 46px rgba(170,55,36,.55); }
.btn-sm { padding: 5px 12px; font-size: 11px; letter-spacing: .06em; }
.btn-xs { padding: 3px 8px; font-size: 10px; letter-spacing: .04em; }

/* ————— loading ————— */
.loading { position: fixed; inset: 0; z-index: 95; background: #0e0c09; display: grid; place-items: center; transition: opacity .7s; }
.loading.gone { opacity: 0; pointer-events: none; }
.loading p { position: absolute; top: 60%; font-size: 11px; letter-spacing: .35em; color: #8f806a; text-transform: uppercase; }
.enso { width: 86px; height: 86px; border-radius: 50%; border: 2px solid transparent; border-top-color: #d8c393; border-right-color: rgba(216,195,147,.2); animation: spin 1.6s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ————— modals ————— */
#modal-root { position: fixed; inset: 0; z-index: 50; pointer-events: none; }
.overlay {
  position: absolute; inset: 0; pointer-events: auto; display: flex; align-items: center; justify-content: center;
  padding: 22px; background: rgba(8, 7, 6, 0.6); backdrop-filter: blur(7px); animation: fadein .25s ease;
}
@keyframes fadein { from { opacity: 0; } }
.sheet {
  width: min(1120px, 96vw); max-height: min(88vh, 900px); display: flex; flex-direction: column;
  background:
    radial-gradient(ellipse at 15% 0%, rgba(255,250,235,.9), transparent 55%),
    linear-gradient(150deg, #f6efdf, #e7dcc5 65%, #dfd2b7);
  border: 1px solid rgba(70, 52, 28, .45);
  box-shadow: 0 30px 100px rgba(0,0,0,.65), inset 0 0 0 5px rgba(255, 250, 235, .4), inset 0 0 60px rgba(120, 95, 55, .12);
  animation: sheetin .35s cubic-bezier(.2,.8,.3,1); position: relative; overflow: hidden;
}
@keyframes sheetin { from { opacity: 0; transform: translateY(22px) scale(.985); } }
.sheet::before {
  content: ''; position: absolute; inset: 8px; border: 1px solid rgba(80, 60, 30, .13); pointer-events: none; z-index: 1;
}
.sheet-head {
  display: flex; align-items: center; gap: 16px; padding: 18px 26px 16px; border-bottom: 1px solid rgba(70,52,28,.22);
  position: relative; flex: 0 0 auto; z-index: 2;
}
.sheet-head .seal {
  width: 42px; height: 42px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #c64b37, #982d23);
  color: #f7ecdb; display: grid; place-items: center; font-family: var(--jp); font-size: 21px; flex: 0 0 auto;
  box-shadow: 0 2px 10px rgba(120,32,22,.3), inset 0 0 12px rgba(0,0,0,.2);
}
.sheet-title { display: flex; flex-direction: column; gap: 2px; }
.sheet-title h2 { margin: 0; font-size: 25px; font-weight: 500; letter-spacing: .08em; line-height: 1; }
.sheet-title small { font-size: 9px; letter-spacing: .26em; color: var(--ink-faint); text-transform: uppercase; }
.sheet-head .spacer { flex: 1; }
.sheet-close {
  width: 34px; height: 34px; border: 1px solid var(--line); background: rgba(255,250,240,.4);
  color: var(--ink-soft); font-size: 20px; line-height: 1; border-radius: 50%; display: grid; place-items: center;
  transition: .18s;
}
.sheet-close:hover { background: var(--verm); color: #fff; border-color: var(--verm); transform: rotate(90deg); }
.sheet-body { padding: 20px 26px 26px; overflow-y: auto; flex: 1 1 auto; z-index: 2; scrollbar-width: thin; scrollbar-color: #b5a17d transparent; }
.sheet-body::-webkit-scrollbar { width: 8px; }
.sheet-body::-webkit-scrollbar-thumb { background: #b5a17d; border-radius: 8px; }
.sheet-foot { padding: 12px 26px; border-top: 1px solid rgba(70,52,28,.18); display: flex; gap: 10px; align-items: center; justify-content: flex-end; background: rgba(230,218,194,.55); flex: 0 0 auto; z-index: 2; }

.tabs { display: flex; gap: 4px; border-bottom: 1px solid rgba(70,52,28,.22); margin-bottom: 16px; flex-wrap: wrap; }
.tab {
  border: 0; background: transparent; padding: 8px 14px 9px; color: var(--ink-faint);
  font-size: 12px; letter-spacing: .1em; position: relative; border-bottom: 2px solid transparent;
}
.tab:hover { color: var(--ink); }
.tab.active { color: var(--verm); border-bottom-color: var(--verm); }
.tab .num { font-size: 9px; background: rgba(60,45,25,.1); padding: 1px 5px; border-radius: 8px; margin-left: 5px; }

.panel-grid { display: grid; gap: 14px; }
.grid-2 { grid-template-columns: 1fr 1fr; }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.split { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr); gap: 18px; }
.split-wide { display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; }

.card {
  background: rgba(255, 250, 237, .62); border: 1px solid rgba(80,60,35,.22);
  padding: 14px; border-radius: 2px; position: relative; transition: .18s;
}
.card.hoverable:hover { border-color: rgba(80,60,35,.45); box-shadow: 0 8px 26px rgba(80,60,35,.14); transform: translateY(-1px); }
.card.dim { opacity: .55; }
.card .card-top { display: flex; align-items: flex-start; gap: 10px; }
.card h3 { margin: 0 0 3px; font-size: 17px; font-weight: 600; letter-spacing: .02em; line-height: 1.1; }
.card .sub { font-size: 10px; letter-spacing: .15em; color: var(--ink-faint); text-transform: uppercase; }
.card .kanji-badge {
  width: 40px; height: 40px; flex: 0 0 auto; border: 1px solid rgba(80,60,35,.3);
  display: grid; place-items: center; font-family: var(--jp); font-size: 19px; color: var(--verm);
  background: rgba(255,250,235,.6); border-radius: 50%;
}
.card .price { font-size: 19px; color: var(--ink); font-weight: 500; }
.card .price small { font-size: 10px; color: var(--ink-faint); letter-spacing: .1em; }

.tag { display: inline-block; font-size: 9px; letter-spacing: .1em; padding: 2px 6px; border: 1px solid rgba(80,60,35,.3); border-radius: 2px; color: var(--ink-soft); background: rgba(255,250,240,.4); text-transform: uppercase; }
.tag.red { border-color: rgba(179,58,43,.45); color: var(--verm); background: rgba(179,58,43,.06); }
.tag.green { border-color: rgba(92,114,84,.45); color: #4a6142; background: rgba(92,114,84,.08); }
.tag.gold { border-color: rgba(182,145,79,.55); color: #8b6825; background: rgba(182,145,79,.1); }
.tag.purple { border-color: rgba(112,75,130,.45); color: #6b4b7a; background: rgba(112,75,130,.07); }
.tag.night { border-color: rgba(143,52,52,.5); color: #a54545; background: rgba(40,20,30,.06); }

.bar { height: 6px; background: rgba(60,45,25,.13); border-radius: 6px; overflow: hidden; margin: 4px 0; }
.bar > u { display: block; height: 100%; border-radius: 6px; background: linear-gradient(90deg, #7f9a6d, #a9c48c); transition: width .5s ease; }
.bar.water > u { background: linear-gradient(90deg, #5e84a0, #9bbcd2); }
.bar.style > u { background: linear-gradient(90deg, #b6914f, #e2c88e); }
.bar.health > u { background: linear-gradient(90deg, #8a9e70, #b7cb93); }
.bar.focus > u { background: linear-gradient(90deg, #8b7ba0, #b7a8c9); }
.bar > u.low { background: linear-gradient(90deg, #a64738, #cf6b55) !important; }
.statline { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--ink-faint); letter-spacing: .05em; }

.kv { display: grid; grid-template-columns: auto 1fr; gap: 5px 14px; font-size: 12.5px; }
.kv dt { color: var(--ink-faint); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; padding-top: 1px; }
.kv dd { margin: 0; color: var(--ink); }

.row { display: flex; align-items: center; gap: 10px; }
.row.between { justify-content: space-between; }
.row.wrap { flex-wrap: wrap; }
.grow { flex: 1; }
.muted { color: var(--ink-faint); }
.small { font-size: 11px; }
.tiny { font-size: 9.5px; letter-spacing: .06em; }
.gold { color: #8b6825; }
.verm { color: var(--verm); }
.moss { color: #4a6142; }
.center { text-align: center; }
.mt6 { margin-top: 6px; } .mt10 { margin-top: 10px; } .mt16 { margin-top: 16px; } .mb10 { margin-bottom: 10px; }
.rule { height: 1px; background: rgba(70,52,28,.16); margin: 14px 0; }
.section-label { font-size: 9px; letter-spacing: .24em; text-transform: uppercase; color: var(--ink-faint); margin: 2px 0 8px; display: flex; align-items: center; gap: 8px; }
.section-label::after { content: ''; flex: 1; height: 1px; background: rgba(70,52,28,.14); }

/* preview canvas */
.preview-wrap {
  position: relative; width: 100%; height: 300px; border: 1px solid rgba(80,60,35,.2);
  background: radial-gradient(ellipse at 50% 35%, #3a3329, #1b1814 70%); overflow: hidden; border-radius: 2px;
}
.preview-wrap.tall { height: 360px; }
.preview-wrap canvas { width: 100% !important; height: 100% !important; display: block; }
.preview-caption { position: absolute; left: 0; right: 0; bottom: 0; padding: 24px 14px 10px; background: linear-gradient(transparent, rgba(0,0,0,.7)); color: #eadfc9; font-size: 11px; letter-spacing: .1em; display: flex; justify-content: space-between; align-items: flex-end; }
.preview-caption .jp { font-family: var(--jp); font-size: 17px; letter-spacing: .15em; }
.preview-rotate { position: absolute; top: 10px; right: 10px; font-size: 8px; letter-spacing: .16em; color: rgba(240,230,210,.5); }

/* bonsai cards */
.tree-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 12px; }
.tree-card { padding: 0; overflow: hidden; cursor: pointer; }
.tree-art { height: 112px; position: relative; display: grid; place-items: center; background: linear-gradient(165deg, #2b2820, #17140f); }
.tree-art svg { height: 100px; width: 100%; }
.tree-art .pot { position: absolute; bottom: 9px; left: 50%; transform: translateX(-50%); width: 52px; height: 10px; border-radius: 2px 2px 6px 6px; background: linear-gradient(#7a4a34, #4e2d1f); }
.tree-art .rarity { position: absolute; top: 6px; left: 8px; font-size: 8px; letter-spacing: .12em; color: #d8c393; }
.tree-art .heirloom { position: absolute; top: 6px; right: 8px; color: #d8c393; font-family: var(--jp); font-size: 12px; border: 1px solid rgba(216,195,147,.4); width: 20px; height: 20px; display: grid; place-items: center; }
.tree-card .info { padding: 9px 11px 10px; }
.tree-card h4 { margin: 0 0 2px; font-size: 14.5px; font-weight: 600; }
.tree-card .meta { font-size: 9px; letter-spacing: .1em; color: var(--ink-faint); text-transform: uppercase; }
.tree-card .val { font-size: 14px; color: #8b6825; margin-top: 5px; font-variant-numeric: tabular-nums; }
.tree-card .mini-bars { display: flex; gap: 3px; margin-top: 7px; }
.tree-card .mini-bars u { height: 3px; flex: 1; background: rgba(60,45,25,.13); display: block; }
.tree-card .mini-bars u::after { content: ''; display: block; height: 100%; width: var(--w); background: var(--c); }
.tree-card.selected { outline: 2px solid var(--verm); outline-offset: 1px; }

/* empty state */
.empty { padding: 34px 22px; text-align: center; border: 1px dashed rgba(80,60,35,.3); color: var(--ink-faint); font-size: 13px; }
.empty .big { font-family: var(--jp); font-size: 38px; color: rgba(80,60,35,.25); display: block; margin-bottom: 8px; }

/* meter rows */
.meter-row { margin: 10px 0; }
.meter-row .statline b { font-weight: 600; color: var(--ink-soft); font-size: 11px; }

/* action grid */
.actions { display: grid; grid-template-columns: repeat(2, 1fr); gap: 7px; }
.action-btn {
  display: flex; flex-direction: column; align-items: flex-start; gap: 1px; text-align: left;
  padding: 8px 11px 9px; background: rgba(255,250,238,.6); border: 1px solid rgba(80,60,35,.24);
  border-radius: 2px; color: var(--ink); transition: .15s; position: relative;
}
.action-btn:hover { background: #fffaf0; border-color: rgba(80,60,35,.45); transform: translateY(-1px); }
.action-btn b { font-size: 12.5px; font-weight: 600; letter-spacing: .04em; }
.action-btn small { font-size: 9.5px; color: var(--ink-faint); letter-spacing: .04em; }
.action-btn .cost { position: absolute; right: 8px; top: 8px; font-size: 9px; color: #8b6825; }
.action-btn:disabled { opacity: .4; cursor: not-allowed; transform: none; }
.action-btn.primary { background: rgba(179,58,43,.08); border-color: rgba(179,58,43,.35); }
.action-btn.primary b { color: var(--verm); }

/* forge */
.forge-layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 18px; }
.recipe-list { max-height: 520px; overflow-y: auto; padding-right: 4px; display: flex; flex-direction: column; gap: 5px; }
.recipe {
  display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid rgba(80,60,35,.18);
  background: rgba(255,250,238,.45); border-radius: 2px; cursor: pointer; transition: .15s; text-align: left;
}
.recipe:hover { background: #fffaf0; border-color: rgba(80,60,35,.4); }
.recipe.active { border-color: var(--verm); background: rgba(179,58,43,.06); }
.recipe.locked { opacity: .45; cursor: not-allowed; }
.recipe .r-kanji { font-family: var(--jp); font-size: 18px; width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid rgba(80,60,35,.22); border-radius: 50%; color: var(--verm); flex: 0 0 auto; }
.recipe .r-name { font-size: 13px; font-weight: 600; line-height: 1.15; }
.recipe .r-meta { font-size: 9px; color: var(--ink-faint); letter-spacing: .06em; margin-top: 2px; }
.recipe .r-price { margin-left: auto; font-size: 10px; color: #8b6825; white-space: nowrap; }

.mat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 7px; }
.mat-card { border: 1px solid rgba(80,60,35,.2); padding: 8px 10px; background: rgba(255,250,238,.4); cursor: pointer; transition: .15s; border-radius: 2px; }
.mat-card:hover { border-color: rgba(80,60,35,.4); background: #fffaf0; }
.mat-card.active { border-color: var(--verm); background: rgba(179,58,43,.07); }
.mat-card.locked { opacity: .45; cursor: not-allowed; }
.mat-card b { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; }
.mat-card small { font-size: 9px; color: var(--ink-faint); letter-spacing: .05em; }
.mat-card .m-stats { display: flex; gap: 8px; font-size: 9px; color: var(--ink-faint); margin-top: 3px; }

.forge-stage {
  border: 1px solid rgba(80,60,35,.25); background: radial-gradient(ellipse at 50% 0%, rgba(255,247,230,.8), rgba(232,220,198,.5));
  padding: 20px; min-height: 340px; display: flex; flex-direction: column; border-radius: 2px;
}
.stage-head { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; }
.stage-num { font-family: var(--jp); width: 30px; height: 30px; border-radius: 50%; background: var(--verm); color: #fff3df; display: grid; place-items: center; font-size: 13px; }
.stage-head h3 { margin: 0; font-size: 21px; font-weight: 500; letter-spacing: .04em; }
.stage-desc { font-size: 12px; color: var(--ink-soft); line-height: 1.5; margin: 5px 0 12px; max-width: 520px; }
.stage-bar-wrap { margin: 14px 0 10px; }
.stage-bar { position: relative; height: 34px; border: 1px solid rgba(80,60,35,.35); background: rgba(60,45,25,.1); overflow: hidden; border-radius: 2px; }
.stage-bar .zone { position: absolute; top: 0; bottom: 0; background: linear-gradient(90deg, rgba(92,114,84,.35), rgba(92,114,84,.6), rgba(92,114,84,.35)); border-left: 1px solid rgba(92,114,84,.7); border-right: 1px solid rgba(92,114,84,.7); }
.stage-bar .zone.perfect { background: rgba(182,145,79,.55); border-color: #b6914f; }
.stage-bar .needle { position: absolute; top: -3px; bottom: -3px; width: 3px; background: var(--verm); box-shadow: 0 0 10px rgba(179,58,43,.7); }
.stage-bar .ticks { position: absolute; inset: 0; background-image: repeating-linear-gradient(90deg, transparent 0 9.9%, rgba(70,52,28,.12) 9.9% 10%); }
.stage-bar .fill { position: absolute; inset: 0; width: 0%; background: rgba(182,145,79,.18); }
.stage-feedback { font-size: 12px; min-height: 20px; color: var(--ink-soft); }
.stage-feedback .perfect { color: #8b6825; font-weight: 600; }
.stage-feedback .good { color: #4a6142; }
.stage-feedback .miss { color: var(--verm); }
.stage-result { margin: auto 0; }
.big-grade { font-size: 54px; font-family: var(--jp); color: var(--verm); line-height: 1; }

.hammer-row { display: flex; gap: 20px; align-items: center; }
.hammer-visual { width: 130px; height: 130px; border: 1px solid rgba(80,60,35,.2); background: radial-gradient(circle at 50% 40%, #ffcf6e, #c2601f 35%, #302015 75%); border-radius: 50%; position: relative; box-shadow: inset 0 0 30px rgba(0,0,0,.4); }
.hammer-visual::after { content: ''; position: absolute; inset: 18px; border-radius: 50%; border: 1px dashed rgba(255,230,170,.4); animation: spin 12s linear infinite; }
.hammer-visual .spark { position: absolute; width: 4px; height: 4px; background: #ffe3a0; border-radius: 50%; animation: spark .6s ease-out forwards; }
@keyframes spark { to { transform: translate(var(--dx), var(--dy)) scale(0); opacity: 0; } }

/* auction */
.auction-stage { background: linear-gradient(180deg, #2a241d, #191511); border: 1px solid rgba(216,195,147,.25); padding: 16px; color: #efe5d2; position: relative; overflow: hidden; }
.auction-stage::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse at 75% -10%, rgba(216,120,60,.24), transparent 55%); pointer-events: none; }
.auction-stage .live { display: inline-flex; align-items: center; gap: 6px; font-size: 9px; letter-spacing: .2em; color: #e0a07f; }
.auction-stage .live::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: #d4553f; box-shadow: 0 0 10px #d4553f; animation: pulse 1.2s infinite; }
@keyframes pulse { 50% { opacity: .3; } }
.bid-amount { font-size: 46px; font-weight: 500; color: #f5e4c4; margin: 4px 0 0; letter-spacing: .02em; font-variant-numeric: tabular-nums; line-height: 1; }
.bid-amount small { font-size: 14px; color: #b9a888; letter-spacing: .2em; margin-left: 8px; }
.bid-log { max-height: 190px; overflow-y: auto; margin-top: 12px; border-top: 1px solid rgba(216,195,147,.16); padding-top: 8px; display: flex; flex-direction: column; gap: 4px; }
.bid-line { display: flex; gap: 8px; font-size: 11.5px; color: #b8ab93; animation: fadein .25s; }
.bid-line b { color: #ead9b6; font-weight: 500; }
.bid-line .amt { margin-left: auto; color: #d8b87e; font-variant-numeric: tabular-nums; }
.bid-line.you b { color: #e08a6e; }
.buyer-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.buyer { display: flex; gap: 10px; align-items: center; padding: 9px 10px; border: 1px solid rgba(80,60,35,.2); background: rgba(255,250,238,.5); border-radius: 2px; position: relative; transition: .2s; }
.buyer.out { opacity: .4; filter: grayscale(.5); }
.buyer.leading { border-color: #b6914f; background: rgba(182,145,79,.14); box-shadow: 0 0 0 1px rgba(182,145,79,.3); }
.buyer .face { width: 38px; height: 38px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center; font-family: var(--jp); font-size: 16px; color: #f0e4cc; background: #4d4234; border: 1px solid rgba(255,240,210,.25); }
.buyer.samurai .face { background: linear-gradient(140deg, #5d3a32, #33201d); }
.buyer.monk .face { background: linear-gradient(140deg, #6b5a38, #3b3320); }
.buyer.merchant .face { background: linear-gradient(140deg, #4b5a54, #26302d); }
.buyer.noble .face { background: linear-gradient(140deg, #5b4058, #2c2030); }
.buyer.oni .face { background: linear-gradient(140deg, #6e2634, #2a0e16); color: #f3b9a9; box-shadow: 0 0 16px rgba(160,40,60,.35); }
.buyer b { font-size: 12.5px; display: block; }
.buyer small { font-size: 9px; color: var(--ink-faint); letter-spacing: .06em; }
.buyer .budget { margin-left: auto; text-align: right; font-size: 9px; color: var(--ink-faint); }
.buyer .budget b { font-size: 11px; color: #8b6825; }
.buyer .quote { font-size: 10.5px; color: var(--ink-soft); font-style: italic; margin-top: 3px; line-height: 1.3; }

.auction-item { display: flex; gap: 14px; }
.auction-item .thumb { width: 92px; height: 92px; flex: 0 0 auto; background: radial-gradient(circle at 50% 35%, #353026, #16130f); border: 1px solid rgba(80,60,35,.25); }
.auction-item .thumb canvas { width: 100%; height: 100%; display: block; }
.auction-item h3 { margin: 2px 0 3px; font-size: 18px; }
.appraise { font-size: 11px; color: var(--ink-faint); letter-spacing: .04em; }
.appraise b { color: #8b6825; font-size: 13px; }

.start-price { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; }
.start-price button { padding: 9px 6px; border: 1px solid rgba(80,60,35,.24); background: rgba(255,250,238,.5); font-family: inherit; color: var(--ink); border-radius: 2px; transition: .15s; }
.start-price button b { display: block; font-size: 15px; font-weight: 500; color: #8b6825; }
.start-price button small { font-size: 8.5px; color: var(--ink-faint); letter-spacing: .08em; }
.start-price button:hover { background: #fffaf0; border-color: var(--verm); }
.start-price button.active { border-color: var(--verm); background: rgba(179,58,43,.08); }

/* shop */
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 10px; }
.shop-card { border: 1px solid rgba(80,60,35,.2); background: rgba(255,250,238,.55); padding: 11px 12px; display: flex; flex-direction: column; gap: 6px; border-radius: 2px; transition: .15s; }
.shop-card:hover { border-color: rgba(80,60,35,.4); background: #fffaf0; }
.shop-card h4 { margin: 0; font-size: 14px; font-weight: 600; display: flex; align-items: center; gap: 6px; }
.shop-card .k { font-family: var(--jp); color: var(--verm); font-size: 15px; }
.shop-card p { margin: 0; font-size: 11px; color: var(--ink-faint); line-height: 1.4; flex: 1; }
.shop-card .buy-row { display: flex; align-items: center; justify-content: space-between; margin-top: 2px; }
.shop-card .buy-row b { font-size: 14px; color: #8b6825; font-weight: 500; }

/* estate visual */
.estate-hero { position: relative; height: 170px; border: 1px solid rgba(80,60,35,.2); overflow: hidden; margin-bottom: 14px; background: linear-gradient(180deg, #6b8f9e, #c7cbb1 60%, #6b6f4f); }
.estate-hero .sun { position: absolute; width: 50px; height: 50px; border-radius: 50%; background: radial-gradient(circle, #fbe7b7, rgba(250,220,160,0)); right: 18%; top: 14%; box-shadow: 0 0 50px 20px rgba(255,225,160,.25); }
.estate-hero .ridge { position: absolute; bottom: 30%; left: 0; right: 0; height: 50%; background: linear-gradient(150deg, transparent 35%, #3d4a3c); clip-path: polygon(0 100%, 0 60%, 18% 30%, 34% 55%, 52% 18%, 72% 48%, 88% 22%, 100% 40%, 100% 100%); opacity: .7; }
.estate-hero .ridge2 { position: absolute; bottom: 20%; left: 0; right: 0; height: 42%; background: #4e5c44; clip-path: polygon(0 100%, 0 70%, 12% 45%, 30% 68%, 48% 35%, 68% 60%, 84% 38%, 100% 55%, 100% 100%); opacity: .85; }
.estate-hero .hero-label { position: absolute; left: 14px; bottom: 12px; color: #f3ead6; text-shadow: 0 2px 10px #000; }
.estate-hero .hero-label b { font-size: 19px; font-weight: 500; letter-spacing: .06em; display: block; }
.estate-hero .hero-label small { font-size: 9px; letter-spacing: .2em; color: #d8c9ab; }
.estate-hero .hero-stat { position: absolute; right: 14px; bottom: 14px; display: flex; gap: 8px; }
.estate-hero .hero-stat span { background: rgba(20,17,13,.55); border: 1px solid rgba(216,195,147,.25); padding: 4px 9px; font-size: 10px; color: #e8dcc5; backdrop-filter: blur(4px); }
.estate-hero .hero-stat b { color: #e7c88f; font-weight: 500; }
.upgrade-row { display: grid; grid-template-columns: 46px 1fr auto; gap: 12px; align-items: center; padding: 12px 0; border-bottom: 1px solid rgba(70,52,28,.14); }
.upgrade-row:last-child { border-bottom: 0; }
.upgrade-row .u-icon { width: 46px; height: 46px; border: 1px solid rgba(80,60,35,.25); display: grid; place-items: center; font-family: var(--jp); font-size: 21px; color: var(--verm); background: rgba(255,250,238,.6); border-radius: 50%; }
.upgrade-row h4 { margin: 0 0 2px; font-size: 14.5px; }
.upgrade-row p { margin: 0; font-size: 10.5px; color: var(--ink-faint); line-height: 1.35; }
.upgrade-row .u-right { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.upgrade-row .u-right b { font-size: 13px; color: #8b6825; }
.pips { display: flex; gap: 3px; }
.pips i { width: 12px; height: 4px; background: rgba(60,45,25,.15); display: block; }
.pips i.on { background: var(--verm); }

/* map */
.map-wrap { position: relative; border: 1px solid rgba(80,60,35,.3); background: #dcd6c2; overflow: hidden; height: 400px; }
.map-wrap svg { width: 100%; height: 100%; display: block; }
.map-pin { cursor: pointer; transition: .2s; }
.map-pin:hover circle { r: 9; fill: #b33a2b; }
.map-pin text { font-family: var(--jp); fill: #2c271e; font-size: 13px; pointer-events: none; }
.map-pin .lbl { font-family: var(--serif); font-size: 7px; letter-spacing: .1em; fill: #5a5040; }
.location-list { display: flex; flex-direction: column; gap: 6px; max-height: 400px; overflow-y: auto; }
.location {
  display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid rgba(80,60,35,.18);
  background: rgba(255,250,238,.45); cursor: pointer; border-radius: 2px; transition: .15s; text-align: left;
}
.location:hover { background: #fffaf0; border-color: rgba(80,60,35,.4); }
.location.current { border-color: var(--verm); background: rgba(179,58,43,.06); }
.location .l-kanji { width: 34px; height: 34px; border: 1px solid rgba(80,60,35,.22); border-radius: 50%; display: grid; place-items: center; font-family: var(--jp); font-size: 16px; color: var(--verm); flex: 0 0 auto; }
.location b { font-size: 13px; display: block; }
.location small { font-size: 9.5px; color: var(--ink-faint); letter-spacing: .04em; }
.location .go { margin-left: auto; font-size: 9px; letter-spacing: .14em; color: var(--ink-faint); border: 1px solid rgba(80,60,35,.22); padding: 4px 7px; }
.location:hover .go { background: var(--verm); color: #fff; border-color: var(--verm); }

/* oni */
.oni { background: linear-gradient(160deg, #1d1418, #120d12); color: #e6d7c9; border-color: rgba(160,60,70,.35); }
.oni .sheet-head { border-bottom-color: rgba(160,60,70,.26); }
.oni .sheet-head .seal { background: radial-gradient(circle at 35% 30%, #a33a4c, #591927); box-shadow: 0 0 22px rgba(180,50,80,.4); }
.oni .sheet-title h2 { color: #f0ded2; }
.oni .sheet-title small { color: #a98a86; }
.oni .sheet-body { background: radial-gradient(ellipse at 50% 0%, rgba(120,30,50,.22), transparent 60%); }
.oni .sheet-close { border-color: rgba(180,100,110,.3); color: #d7b9b6; background: rgba(255,255,255,.04); }
.oni .tabs { border-bottom-color: rgba(180,100,110,.2); }
.oni .tab { color: #a88784; }
.oni .tab.active { color: #e29a90; border-bottom-color: #c25a5a; }
.oni .card, .oni .shop-card, .oni .buyer, .oni .location, .oni .mat-card, .oni .recipe { background: rgba(255,255,255,.035); border-color: rgba(180,100,110,.2); color: #e6d7c9; }
.oni .card:hover, .oni .shop-card:hover, .oni .buyer:hover { background: rgba(255,255,255,.06); border-color: rgba(200,120,120,.4); }
.oni h3, .oni h4, .oni .price, .oni .card h3 { color: #f0ded2; }
.oni .sub, .oni .muted, .oni .card .sub, .oni .shop-card p, .oni .buyer small, .oni .appraise, .oni .kv dt { color: #a88784; }
.oni .btn { background: rgba(30,18,22,.8); border-color: rgba(190,100,110,.35); color: #e8d3c4; box-shadow: none; }
.oni .btn:hover { background: rgba(140,40,55,.4); }
.oni .btn-primary { background: linear-gradient(180deg, #a63c4c, #6d1d2b); border-color: #50131f; color: #ffe9df; }
.oni .tag { border-color: rgba(200,120,120,.35); color: #dba9a2; background: rgba(150,50,60,.15); }
.oni .rule { background: rgba(180,100,110,.2); }
.oni .section-label { color: #a88784; }
.oni .section-label::after { background: rgba(180,100,110,.2); }
.oni .sheet-foot { background: rgba(20,12,16,.6); border-top-color: rgba(180,100,110,.2); }
.oni .preview-wrap { border-color: rgba(180,100,110,.3); background: radial-gradient(ellipse at 50% 35%, #2c1722, #0e090d 70%); }

/* commissions */
.commission { border: 1px solid rgba(80,60,35,.2); background: rgba(255,250,238,.55); padding: 11px 13px; border-radius: 2px; }
.commission .c-head { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.commission .c-head b { font-size: 13px; }
.commission .c-head .tag { margin-left: auto; }
.commission p { margin: 0 0 6px; font-size: 11px; color: var(--ink-soft); }
.commission .c-foot { display: flex; align-items: center; justify-content: space-between; font-size: 10px; }
.commission .c-foot b { color: #8b6825; font-size: 13px; }
.commission.done { border-color: rgba(92,114,84,.4); }

/* codex */
.codex-chips { display: flex; gap: 5px; flex-wrap: wrap; margin-bottom: 14px; }
.codex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 9px; }
.codex-card { border: 1px solid rgba(80,60,35,.18); padding: 10px 12px; background: rgba(255,250,238,.42); }
.codex-card b { display: flex; gap: 6px; align-items: center; font-size: 13px; }
.codex-card .k { font-family: var(--jp); color: var(--verm); font-size: 14px; }
.codex-card p { margin: 4px 0 0; font-size: 10.5px; color: var(--ink-faint); line-height: 1.4; }
.codex-section h3 { font-size: 11px; letter-spacing: .2em; color: var(--ink-faint); margin: 18px 0 8px; font-weight: 500; }

/* meditate */
.meditate-veil { position: fixed; inset: 0; z-index: 45; display: grid; place-items: center; background: rgba(8,7,5,.72); backdrop-filter: blur(8px); color: #e8ddc8; text-align: center; animation: fadein .5s; }
.meditate-veil .enso2 { width: 110px; height: 110px; border-radius: 50%; border: 1px solid rgba(216,195,147,.35); display: grid; place-items: center; font-family: var(--jp); font-size: 38px; color: #d8c393; margin: 0 auto 18px; animation: breathe 4s ease-in-out infinite; }
@keyframes breathe { 50% { transform: scale(1.08); border-color: rgba(216,195,147,.7); } }
.meditate-veil p { font-size: 11px; letter-spacing: .32em; color: #a8987e; text-transform: uppercase; }

/* notifications etc */
.offline-pill { display: inline-flex; align-items: center; gap: 6px; font-size: 10px; letter-spacing: .1em; color: #8b6825; border: 1px solid rgba(182,145,79,.4); background: rgba(182,145,79,.08); padding: 4px 9px; border-radius: 20px; }
.pulse-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--verm); animation: pulse 1.5s infinite; }

/* responsive */
@media (max-width: 980px) {
  .stat.weather { display: none; }
  #quests { display: none !important; }
  .split, .split-wide, .forge-layout { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .sheet { max-height: 92vh; }
  .sheet-body { padding: 16px 16px 20px; }
  .sheet-head { padding: 14px 16px; }
  .sheet-title h2 { font-size: 22px; }
  .auction-stage { padding: 12px; }
  .bid-amount { font-size: 34px; }
  #compass { display: none; }
  .brand-text { display: none; }
  .brand .crest { width: 40px; height: 40px; font-size: 22px; }
}
@media (max-width: 700px) {
  #hud { padding: 10px 12px; gap: 8px; }
  .stats { gap: 4px; }
  .stat { min-width: 0; padding: 5px 8px; gap: 6px; }
  .stat .stat-k { width: 24px; height: 24px; font-size: 16px; }
  .stat small { font-size: 6.5px; }
  .stat b { font-size: 13px; }
  .stat.money b { font-size: 14px; }
  .stat.date b { font-size: 10px; }
  .stat.rep { display: none; }
  .hud-actions { gap: 3px; }
  .icon-btn { width: 38px; height: 38px; font-size: 13px; }
  .icon-btn small { display: none; }
  .brand .crest { width: 36px; height: 36px; font-size: 20px; }
  #dock { width: calc(100% - 16px); justify-content: space-between; bottom: 8px; }
  #dock button { width: 16.6%; padding: 5px 0 4px; }
  #dock button span { font-size: 18px; width: 28px; height: 28px; }
  #dock button b { font-size: 7px; letter-spacing: .06em; }
  #dock button small { display: none; }
  #focus-wrap { bottom: 90px; left: 12px; width: 120px; }
  #toasts { top: 64px; right: 10px; max-width: 260px; }
  .toast { font-size: 11.5px; padding: 7px 10px; }
  .overlay { padding: 8px; }
  .sheet { width: 100%; max-height: 94vh; }
  .sheet::before { inset: 5px; }
  .sheet-head { gap: 10px; padding: 11px 13px; }
  .sheet-head .seal { width: 34px; height: 34px; font-size: 17px; }
  .sheet-title h2 { font-size: 19px; }
  .sheet-title small { font-size: 7px; letter-spacing: .16em; }
  .sheet-body { padding: 12px 13px 18px; }
  .sheet-foot { padding: 9px 13px; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .tree-grid { grid-template-columns: repeat(2, 1fr); gap: 7px; }
