export function save(state) {
  try {
    state.lastSaved = Date.now();
    const data = JSON.parse(JSON.stringify(state));
    localStorage.setItem(SAVE_KEY, JSON.stringify(data));
    return true;
  } catch (e) {
    console.warn('Save failed', e);
    return false;
  }
}

export function load() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data.version) return null;
    const base = initialState();
    const state = { ...base, ...data };
    state.stats = { ...base.stats, ...(data.stats || {}) };
    state.settings = { ...base.settings, ...(data.settings || {}) };
    state.hires = { ...base.hires, ...(data.hires || {}) };
    state.seeds = { ...base.seeds, ...(data.seeds || {}) };
    state.materials = { ...base.materials, ...(data.materials || {}) };
    state.trees = (data.trees || []).map((t) => ({ ...createTree(t.sp, t), ...t }));
    state.weapons = (data.weapons || []).map((w) => ({ ...createWeapon(w.type, w), ...w }));
    return state;
  } catch (e) {
    console.warn('Load failed', e);
    return null;
  }
}

export function clearSave() {
  try { localStorage.removeItem(SAVE_KEY); } catch (e) { /* ignore */ }
}

export function treeCapacity(state) {
  return 4 + state.gardenLevel * 4;
}

export function beautyOf(state) {
  let beauty = 4 + state.gardenLevel * 6;
  for (const d of state.decor) beauty += DECOR[d]?.beauty || 0;
  for (const t of state.trees) if (t.heirloom) beauty += Math.min(30, treeValue(t) / 900);
  beauty += state.misthouseLevel * 4;
  return Math.round(beauty);
}

export function dailyWages(state) {
  return (state.hires.gardener || 0) * 55 + (state.hires.assistant || 0) * 70;
}

export function visitorIncome(state) {
  const b = beautyOf(state);
  const rep = state.rep;
  return Math.round((b * 6 + b * rep * 0.04) / 10) * 10;
}

import * as THREE from 'three';
import { SPECIES, POTS, seasonOf } from './data.js';

export function seededRandom(seed) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return function () {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

const matCache = new Map();
function leafMat(color, emissive = 0x000000, emissiveIntensity = 0, opts = {}) {
  const key = `${color}-${emissive}-${emissiveIntensity}-${opts.rough ?? 0.85}`;
  if (matCache.has(key)) return matCache.get(key);
  const m = new THREE.MeshStandardMaterial({
    color, emissive, emissiveIntensity, roughness: opts.rough ?? 0.85, metalness: 0,
    flatShading: true, side: THREE.DoubleSide,
  });
  matCache.set(key, m);
  return m;
}

function taperedSegment(a, b, r1, r2, material, radial = 5) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 0.001) return null;
  const geo = new THREE.CylinderGeometry(r2, r1, len, radial, 1);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  mesh.castShadow = true;
  return mesh;
}

export function makePot(tier = 0, scale = 1) {
  const g = new THREE.Group();
  const potDef = POTS[tier] || POTS[0];
  const colors = [0x8a563c, 0x4f6a66, 0x5a4a3a, 0x3b4048, 0x2a1820];
  const bases = [0x7d6349, 0x6f8078, 0x50402f, 0x353a42, 0x3a1a24];
  const col = tier === 4 ? 0x3a1822 : bases[tier];
  const rimCol = tier === 4 ? 0x8b2d38 : colors[tier];
  const bodyMat = new THREE.MeshStandardMaterial({ color: col, roughness: 0.72, metalness: 0.04, flatShading: false });
  const rimMat = new THREE.MeshStandardMaterial({ color: rimCol, roughness: 0.6, metalness: tier >= 2 ? 0.25 : 0.05 });
  const w = 1.25 * scale, d = 0.8 * scale, h = 0.36 * scale;

  // body (slightly tapered)
  const body = new THREE.Mesh(new THREE.CylinderGeometry(w * 0.46, w * 0.36, h, 4, 1), bodyMat);
  body.rotation.y = Math.PI / 4;
  body.scale.z = d / w;
  body.position.y = h / 2 + 0.02;
  body.castShadow = true;
  g.add(body);

  // rim
  const rim = new THREE.Mesh(new THREE.BoxGeometry(w * 1.02, 0.09 * scale, d * 1.12), rimMat);
  rim.position.y = h + 0.045;
  rim.castShadow = true;
  g.add(rim);

  // feet
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.1 * scale, 0.09 * scale, 0.1 * scale), bodyMat);
    foot.position.set(sx * w * 0.3, 0.045, sz * d * 0.34);
    g.add(foot);
  }

  // soil
  const soil = new THREE.Mesh(new THREE.CylinderGeometry(w * 0.42, w * 0.42, 0.06, 12), new THREE.MeshStandardMaterial({ color: 0x2b2119, roughness: 1 }));
  soil.scale.z = d / w;
  soil.position.y = h + 0.05;
  g.add(soil);

  // moss
  const mossMat = new THREE.MeshStandardMaterial({ color: 0x4f6b3a, roughness: 1, flatShading: true });
  for (let i = 0; i < 6; i++) {
    const m = new THREE.Mesh(new THREE.IcosahedronGeometry(0.11 * scale, 0), mossMat);
    const ang = i * 1.7;
    m.position.set(Math.cos(ang) * w * 0.26, h + 0.07, Math.sin(ang) * d * 0.24);
    m.scale.set(1, 0.35, 1);
    m.scale.multiplyScalar(0.7 + (i % 3) * 0.25);
    g.add(m);
  }

  // accent stone
  const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(0.1 * scale, 0), new THREE.MeshStandardMaterial({ color: 0x77736a, roughness: 0.95, flatShading: true }));
  rock.position.set(w * 0.16, h + 0.1, d * 0.05);
  rock.scale.set(1.2, 0.7, 1);
  g.add(rock);

  g.userData.potTop = h + 0.08;
  g.userData.potWidth = w;
  return g;
}

function addPads(group, pos, sp, color, emissive, count, spread, size, rng, flatten = 0.5) {
  for (let i = 0; i < count; i++) {
    const a = rng() * Math.PI * 2;
    const r = spread * Math.pow(rng(), 0.6);
    const s = size * (0.65 + rng() * 0.6);
    const geo = new THREE.IcosahedronGeometry(s, 1);
    const m = new THREE.Mesh(geo, leafMat(color, emissive, sp.supernatural ? 0.85 : 0, { rough: 0.85 }));
    m.position.set(pos.x + Math.cos(a) * r, pos.y + (rng() - 0.35) * s * 0.9, pos.z + Math.sin(a) * r);
    m.scale.set(1.15, flatten * (0.8 + rng() * 0.4), 1.15);
    m.rotation.set(rng() * 2, rng() * 3, rng() * 2);
    m.castShadow = true;
    group.add(m);
  }
}

function addFlowers(group, pos, color, count, spread, rng, size = 0.07) {
  const mat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.12, roughness: 0.8 });
  for (let i = 0; i < count; i++) {
    const f = new THREE.Mesh(new THREE.IcosahedronGeometry(size * (0.7 + rng() * 0.7), 0), mat);
    f.position.set(pos.x + (rng() - 0.5) * spread, pos.y + (rng() - 0.5) * spread * 0.5, pos.z + (rng() - 0.5) * spread);
    group.add(f);
  }
}

function buildTrunk(group, sp, tree, rng, seasonId) {
  const age = Math.min(tree.age, 14);
  const style = tree.style / 100;
  const height = 1.15 + Math.min(age, 10) * 0.115 + style * 0.35;
  const lean = (rng() - 0.5) * (0.28 + style * 0.5);
  const leanZ = (rng() - 0.5) * 0.25;
  const radius = 0.09 + Math.min(age, 12) * 0.014 + style * 0.025;
  const barkColor = sp.supernatural ? (sp.id === 'yomi' ? 0x4a2a44 : 0x3a4a46) : (sp.id === 'cherry' ? 0x513b35 : sp.id === 'bamboo' ? 0x7d8a4e : 0x5a4635);
  const barkMat = new THREE.MeshStandardMaterial({ color: barkColor, roughness: 0.95, flatShading: true, emissive: sp.supernatural ? (sp.id === 'yomi' ? 0x3a0a2a : 0x0a2a28) : 0x000000, emissiveIntensity: sp.supernatural ? 0.5 : 0 });
  const leafColor = sp.leaf[seasonId] ?? sp.leaf.summer;

  if (sp.form === 'bamboo') {
    const culms = 3 + Math.floor(rng() * 3) + Math.round(style * 3);
    for (let c = 0; c < culms; c++) {
      const h = height * (0.65 + rng() * 0.55) * (c === 0 ? 1.15 : 0.9);
      const bx = (rng() - 0.5) * 0.45, bz = (rng() - 0.5) * 0.22;
      const leanX = (rng() - 0.5) * 0.12, leanZ = (rng() - 0.5) * 0.12;
      const a = new THREE.Vector3(bx, 0, bz);
      const b = new THREE.Vector3(bx + leanX * h, h, bz + leanZ * h);
      const seg = taperedSegment(a, b, radius * 0.42, radius * 0.22, barkMat, 6);
      if (seg) group.add(seg);
      for (let n = 1; n < 5; n++) {
        const ny = (h / 5) * n;
        const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.36, 0.014, 3, 6), barkMat);
        ring.position.set(bx + leanX * ny, ny, bz + leanZ * ny);
        ring.rotation.x = Math.PI / 2;
        group.add(ring);
      }
      const base = new THREE.Vector3(bx + leanX * h, h, bz + leanZ * h);
      addPads(group, base, sp, leafColor, 0x000000, 3, 0.28, 0.24, rng, 0.35);
    }
    return;
  }

  const segments = [];
  let cursor = new THREE.Vector3(0, 0, 0);
  const points = 4;
  for (let i = 0; i < points; i++) {
    const t = (i + 1) / points;
    const next = new THREE.Vector3(
      lean * t + (rng() - 0.5) * 0.09 * (1 - t),
      height * t,
      leanZ * t + (rng() - 0.5) * 0.08 * (1 - t),
    );
    if (tree.wiring) {
      next.x += Math.sin(t * 6 + tree.variant) * 0.06;
      next.z += Math.cos(t * 5 + tree.variant) * 0.06;
    }
    const r1 = radius * (1 - i / points * 0.55);
    const r2 = radius * (1 - (i + 1) / points * 0.6);
    const seg = taperedSegment(cursor, next, r1, r2, barkMat, 6);
    if (seg) { group.add(seg); segments.push({ a: cursor.clone(), b: next.clone(), r: r1, t }); }
    cursor = next;
  }

  const top = cursor.clone();
  const branches = 3 + Math.round(style * 3) + (age > 5 ? 1 : 0);
  const branchTips = [];
  for (let i = 0; i < branches; i++) {
    const seg = segments[Math.min(segments.length - 1, 1 + Math.floor(rng() * (segments.length - 1)))];
    const start = seg.b.clone().add(new THREE.Vector3(0, -0.05, 0));
    const ang = (i / branches) * Math.PI * 2 + rng() * 0.8 + tree.variant * 0.13;
    const spread = 0.45 + style * 0.55 + rng() * 0.4;
    const len = (0.45 + rng() * 0.45) * (0.7 + age * 0.06) * (0.7 + style * 0.5);
    const dir = new THREE.Vector3(Math.cos(ang) * spread, (rng() - 0.35) * 0.5 + 0.22, Math.sin(ang) * spread).normalize();
    const end = start.clone().addScaledVector(dir, len);
    const br = taperedSegment(start, end, radius * 0.36, radius * 0.15, barkMat, 5);
    if (br) group.add(br);
    branchTips.push({ p: end, dir, len });

    if (rng() > 0.25) {
      const dir2 = dir.clone().add(new THREE.Vector3((rng() - 0.5) * 1.3, 0.25, (rng() - 0.5) * 1.3)).normalize();
      const end2 = end.clone().addScaledVector(dir2, len * 0.55);
      const br2 = taperedSegment(end, end2, radius * 0.17, radius * 0.09, barkMat, 4);
      if (br2) group.add(br2);
      branchTips.push({ p: end2, dir: dir2, len: len * 0.55 });
      if (sp.form === 'wisteria' || sp.form === 'cherry') addFlowerCluster(group, end2, sp, leafColor, rng);
    } else if (sp.form === 'wisteria' || sp.form === 'cherry' || sp.form === 'flower') {
      addFlowerCluster(group, end, sp, leafColor, rng);
    }
  }

  // apex crown
  addPads(group, top, sp, leafColor, 0x000000, 2 + Math.round(style * 2), 0.3, sp.form === 'pine' ? 0.3 : 0.34, rng, sp.form === 'pine' ? 0.32 : 0.52);

  for (const tip of branchTips) {
    if (sp.form === 'pine' || sp.form === 'juniper') {
      addPads(group, tip.p, sp, leafColor, 0x000000, 2, tip.len * 0.55, 0.24 + style * 0.1, rng, 0.32);
    } else if (sp.form === 'flower') {
      addPads(group, tip.p, sp, leafColor, 0x000000, 2, tip.len * 0.4, 0.22, rng, 0.45);
      addFlowers(group, tip.p, 0xe98aa5, 7 + Math.round(style * 8), tip.len * 0.7, rng, 0.055);
    } else {
      addPads(group, tip.p, sp, leafColor, 0x000000, 2 + Math.round(style * 2), tip.len * 0.45, 0.26, rng, 0.48);
    }
  }

  // exposed roots
  const rootMat = barkMat;
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + rng();
    const root = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.055, 0.35, 5), rootMat);
    root.position.set(Math.cos(a) * 0.12, 0.03, Math.sin(a) * 0.12);
    root.rotation.z = Math.PI / 2 - 0.15;
    root.rotation.y = -a;
    g2root(group, root, a);
  }
}

function g2root(group, root, a) {
  root.rotation.order = 'YXZ';
  root.rotation.y = -a;
  group.add(root);
}

function addFlowerCluster(group, pos, sp, leafColor, rng) {
  if (sp.id === 'wisteria') {
    const mat = new THREE.MeshStandardMaterial({ color: 0xa474c9, emissive: 0x5a2c7a, emissiveIntensity: 0.25, roughness: 0.8, flatShading: true });
    for (let i = 0; i < 3; i++) {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.45 + rng() * 0.3, 5), mat);
      cone.position.set(pos.x + (rng() - 0.5) * 0.28, pos.y - 0.2, pos.z + (rng() - 0.5) * 0.28);
      cone.rotation.x = Math.PI;
      group.add(cone);
    }
  } else if (sp.id === 'cherry') {
    addPads(group, pos, sp, 0xf3b7c8, 0x5a2030, 3, 0.25, 0.27, rng, 0.48);
  }
}

export function createBonsai(tree, seasonId = 'spring', opts = {}) {
  const group = new THREE.Group();
  const sp = SPECIES[tree.sp] || SPECIES.maple;
  const rng = seededRandom((tree.variant || 1) * 7919 + (tree.sp?.length || 3) * 137 + Math.round(tree.age * 10));
  const potScale = opts.scale ?? 1;
  const pot = makePot(tree.pot || 0, potScale);
  group.add(pot);
  const treeGroup = new THREE.Group();
  treeGroup.position.y = pot.userData.potTop || 0.44;
  group.add(treeGroup);

  buildTrunk(treeGroup, sp, tree, rng, seasonId);

  // overall size by age/style
  const ageScale = 0.72 + Math.min(tree.age, 12) * 0.045 + Math.min(tree.style, 100) * 0.0016;
  treeGroup.scale.setScalar(ageScale * (opts.treeScale ?? 1));

  // gentle sway marker
  group.userData.sway = treeGroup;
  group.userData.sp = sp.id;
  group.userData.treeId = tree.id;
  group.userData.isBonsai = true;

  if (opts.glow) {
    const light = new THREE.PointLight(sp.supernatural ? 0x9a4fd4 : 0xffd9a0, 0.6, 4, 2);
    light.position.y = 1.2;
    group.add(light);
  }

  group.traverse((o) => { if (o.isMesh) { o.castShadow = !!opts.castShadow; o.receiveShadow = false; } });
  return group;
}

import * as THREE from 'three';
import { MATERIALS, WEAPON_TYPES } from './data.js';

const matCache = new Map();
function steelMat(matId, supernatural, q = 60) {
  const key = `steel-${matId}-${supernatural}-${q}`;
  if (matCache.has(key)) return matCache.get(key);
  const base = MATERIALS[matId]?.color ?? 0xd6dde0;
  const color = new THREE.Color(base);
  const m = new THREE.MeshStandardMaterial({
    color,
    metalness: 0.92,
    roughness: 0.22 - q * 0.0008,
    emissive: supernatural ? (matId === 'onisteel' ? 0x4a0a1c : 0x0a2a24) : 0x000000,
    emissiveIntensity: supernatural ? 0.55 : 0,
    envMapIntensity: 1.2,
    flatShading: false,
  });
  matCache.set(key, m);
  return m;
}

function woodMat(color = 0x3f2a1c) {
  const key = 'wood' + color;
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshStandardMaterial({ color, roughness: 0.85, metalness: 0.02, flatShading: true }));
  return matCache.get(key);
}

function brassMat() {
  if (!matCache.has('brass')) matCache.set('brass', new THREE.MeshStandardMaterial({ color: 0xb08a44, metalness: 0.85, roughness: 0.32 }));
  return matCache.get('brass');
}
function lacquerMat(color = 0x1c1a20) {
  const key = 'lacquer' + color;
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshStandardMaterial({ color, roughness: 0.28, metalness: 0.25 }));
  return matCache.get(key);
}

let wrapTexture = null;
function getWrapTexture(supernatural = false) {
  if (supernatural) {
    const c = document.createElement('canvas'); c.width = 64; c.height = 64;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#2a0e18'; ctx.fillRect(0, 0, 64, 64);
    ctx.strokeStyle = '#c49452'; ctx.lineWidth = 5;
    for (let i = -64; i < 128; i += 20) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 40, 64); ctx.stroke(); }
    const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(2, 3);
    return t;
  }
  if (wrapTexture) return wrapTexture;
  const c = document.createElement('canvas'); c.width = 64; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#19161a'; ctx.fillRect(0, 0, 64, 64);
  ctx.strokeStyle = '#c9b98f'; ctx.lineWidth = 3;
  for (let i = -64; i < 128; i += 16) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 24, 64); ctx.stroke(); }
  for (let i = 128; i > -64; i -= 16) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i - 24, 64); ctx.stroke(); }
  wrapTexture = new THREE.CanvasTexture(c);
  wrapTexture.wrapS = wrapTexture.wrapT = THREE.RepeatWrapping;
  wrapTexture.repeat.set(1.5, 2.5);
  return wrapTexture;
}

function handleMesh(len = 0.62, supernatural = false, color = null, radius = 0.055) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({
    map: getWrapTexture(supernatural), color: color || 0xffffff, roughness: 0.62, metalness: 0.12,
  });
  const h = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.9, radius, len, 10), mat);
  h.position.y = len / 2;
  h.castShadow = true;
  g.add(h);
  const pommel = new THREE.Mesh(new THREE.CylinderGeometry(radius * 1.05, radius * 1.0, 0.045, 10), brassMat());
  pommel.position.y = 0.02;
  g.add(pommel);
  const collar = new THREE.Mesh(new THREE.CylinderGeometry(radius * 1.1, radius * 1.1, 0.04, 10), brassMat());
  collar.position.y = len - 0.02;
  g.add(collar);
  return g;
}

function bladeShapeGeometry(len, width, curve, thickness = 0.05) {
  const s = new THREE.Shape();
  s.moveTo(-width * 0.5, 0);
  s.quadraticCurveTo(curve * 0.55, len * 0.55, curve, len);
  s.quadraticCurveTo(curve * 0.55 + width * 0.35, len * 0.92, width * 0.52 + curve * 0.15, len * 0.78);
  s.quadraticCurveTo(width * 0.62, len * 0.35, width * 0.5, 0);
  s.lineTo(-width * 0.5, 0);
  const geo = new THREE.ExtrudeGeometry(s, { depth: thickness, bevelEnabled: true, bevelSize: 0.008, bevelThickness: 0.008, bevelSegments: 1, steps: 1 });
  geo.translate(0, 0, -thickness / 2);
  return geo;
}

function katanaLike({ bladeLen = 2.0, width = 0.075, curve = 0.18, handleLen = 0.42, matId = 'iron', quality = 60, supernatural = false, wrapColor = 0x1b1a1f, guard = 'round' }) {
  const g = new THREE.Group();
  const steel = steelMat(matId, supernatural, quality);
  const blade = new THREE.Mesh(bladeShapeGeometry(bladeLen, width, curve), steel);
  blade.position.y = handleLen + 0.08;
  blade.castShadow = true;
  g.add(blade);

  const habaki = new THREE.Mesh(new THREE.BoxGeometry(width * 1.5, 0.075, 0.09), brassMat());
  habaki.position.y = handleLen + 0.06;
  g.add(habaki);

  let tsuba;
  if (guard === 'square') {
    tsuba = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.03, 0.22), brassMat());
  } else {
    tsuba = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 0.028, 16), brassMat());
    tsuba.rotation.x = Math.PI / 2;
  }
  tsuba.position.y = handleLen + 0.012;
  tsuba.castShadow = true;
  g.add(tsuba);
  const tsubaDetail = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.012, 4, 16), lacquerMat(0x2a2119));
  tsubaDetail.position.y = handleLen + 0.012;
  tsubaDetail.rotation.x = Math.PI / 2;
  g.add(tsubaDetail);

  const handle = handleMesh(handleLen, supernatural, wrapColor);
  g.add(handle);

  if (supernatural) {
    const glow = new THREE.Mesh(new THREE.PlaneGeometry(bladeLen * 0.75, width * 3), new THREE.MeshBasicMaterial({ color: matId === 'onisteel' ? 0xff3355 : 0x4fffd0, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
    glow.position.set(curve * 0.8, handleLen + bladeLen * 0.55, 0);
    glow.rotation.z = -0.09;
    g.add(glow);
  }
  return g;
}

function kunaiMesh(matId, quality, supernatural) {
  const g = new THREE.Group();
  const steel = steelMat(matId, supernatural, quality);
  const s = new THREE.Shape();
  s.moveTo(0, 0); s.lineTo(0.11, 0.22); s.lineTo(0, 0.62); s.lineTo(-0.11, 0.22); s.closePath();
  const bl = new THREE.Mesh(new THREE.ExtrudeGeometry(s, { depth: 0.03, bevelEnabled: true, bevelSize: 0.01, bevelThickness: 0.01, bevelSegments: 1 }), steel);
  bl.position.y = 0.2;
  bl.position.z = -0.015;
  g.add(bl);
  const h = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.04, 0.24, 8), woodMat(0x2d241b));
  h.position.y = 0.1;
  g.add(h);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.018, 5, 12), brassMat());
  ring.position.y = -0.08;
  ring.rotation.x = Math.PI / 2;
  g.add(ring);
  return g;
}

function saiMesh(matId, quality, supernatural) {
  const g = new THREE.Group();
  const steel = steelMat(matId, supernatural, quality);
  const h = handleMesh(0.36, supernatural);
  g.add(h);
  const guard = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.03, 10), brassMat());
  guard.position.y = 0.36;
  g.add(guard);
  const center = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.045, 0.68, 8), steel);
  center.position.y = 0.72;
  g.add(center);
  for (const sx of [-1, 1]) {
    const prong = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.035, 0.32, 6), steel);
    prong.position.set(sx * 0.11, 0.55, 0);
    prong.rotation.z = sx * 0.28;
    g.add(prong);
  }
  return g;
}

function poleArm(kind, matId, quality, supernatural) {
  const g = new THREE.Group();
  const steel = steelMat(matId, supernatural, quality);
  const shaftLen = kind === 'naginata' ? 2.5 : 2.7;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.045, shaftLen, 8), woodMat(0x3b2a1d));
  shaft.position.y = shaftLen / 2;
  shaft.castShadow = true;
  g.add(shaft);
  for (let i = 0; i < 4; i++) {
    const wrap = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.05, 8), lacquerMat(0x20242a));
    wrap.position.y = 0.34 + i * 0.12;
    g.add(wrap);
  }
  if (kind === 'naginata') {
    const blade = new THREE.Mesh(bladeShapeGeometry(1.05, 0.11, 0.16), steel);
    blade.position.y = shaftLen;
    blade.rotation.z = Math.PI;
    blade.castShadow = true;
    g.add(blade);
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.07, 0.12, 8), brassMat());
    collar.position.y = shaftLen + 0.02;
    g.add(collar);
  } else {
    const s = new THREE.Shape();
    s.moveTo(0, 0); s.lineTo(0.07, 0.16); s.lineTo(0, 0.6); s.lineTo(-0.07, 0.16); s.closePath();
    const tip = new THREE.Mesh(new THREE.ExtrudeGeometry(s, { depth: 0.035, bevelEnabled: true, bevelSize: 0.006, bevelThickness: 0.006, bevelSegments: 1 }), steel);
    tip.position.y = shaftLen;
    tip.position.z = -0.017;
    g.add(tip);
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.065, 0.1, 8), brassMat());
    collar.position.y = shaftLen + 0.01;
    g.add(collar);
  }
  return g;
}

function bowMesh(matId, quality, supernatural) {
  const g = new THREE.Group();
  const wood = new THREE.MeshStandardMaterial({ color: MATERIALS[matId]?.color || 0x5a3b25, roughness: 0.55, metalness: 0.1, emissive: supernatural ? 0x0a2a24 : 0, emissiveIntensity: 0.5 });
  const pts = [];
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    const y = t * 2.3;
    const x = Math.sin(t * Math.PI) * (t > 0.62 ? 0.28 : 0.36) - 0.2;
    pts.push(new THREE.Vector3(x, y, 0));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 0.035, 6, false), wood);
  tube.castShadow = true;
  g.add(tube);
  for (const cap of [0, 1]) {
    const c = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.035, 0.12, 8), brassMat());
    c.position.copy(curve.getPoint(cap));
    g.add(c);
  }
  const stringMat = new THREE.LineBasicMaterial({ color: 0xe8ddc2, transparent: true, opacity: 0.8 });
  const strGeo = new THREE.BufferGeometry().setFromPoints([pts[0], new THREE.Vector3(-0.28, 0.95, 0), pts[pts.length - 1]]);
  g.add(new THREE.Line(strGeo, stringMat));
  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.46, 8), lacquerMat(0x1a2026));
  grip.position.set(-0.08, 1.12, 0);
  grip.rotation.z = -0.06;
  g.add(grip);
  return g;
}

function armourMesh(matId, quality, supernatural) {
  const g = new THREE.Group();
  const lacquer = new THREE.MeshStandardMaterial({ color: 0x6d1f26, roughness: 0.35, metalness: 0.2, emissive: supernatural ? 0x2a0510 : 0, emissiveIntensity: 0.4 });
  const gold = brassMat();
  const dark = lacquerMat(0x17151a);
  // stand
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.06, 0.4), woodMat(0x32241a));
  base.position.y = 0.03;
  g.add(base);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 1.5, 8), woodMat(0x32241a));
  pole.position.y = 0.78;
  g.add(pole);
  // chest
  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.58, 0.3, 1, 1, 1), lacquer);
  chest.position.y = 1.28;
  g.add(chest);
  for (let i = 0; i < 4; i++) {
    const plate = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.1, 0.31), i % 2 ? gold : lacquer);
    plate.position.y = 1.02 + i * 0.16;
    g.add(plate);
  }
  // shoulders
  for (const sx of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const p = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.07, 0.26), lacquer);
      p.position.set(sx * (0.42 + i * 0.05), 1.48 - i * 0.05, 0);
      p.rotation.z = sx * 0.24;
      g.add(p);
    }
  }
  // skirt
  for (let i = 0; i < 5; i++) {
    const p = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.34, 0.06), i % 2 ? gold : lacquer);
    p.position.set(-0.26 + i * 0.13, 0.88, 0.17);
    p.rotation.x = -0.12;
    g.add(p);
  }
  // helmet
  const helm = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 8, 0, Math.PI * 2, 0, Math.PI / 2), lacquer);
  helm.position.y = 1.72;
  g.add(helm);
  const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.3, 0.045, 12), lacquer);
  brim.position.y = 1.67;
  g.add(brim);
  const crest = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.26, 0.06), gold);
  crest.position.y = 1.9;
  crest.rotation.z = 0.3;
  g.add(crest);
  for (const sx of [-1, 1]) {
    const horn = new THREE.Mesh(new THREE.ConeGeometry(0.03, 0.26, 6), gold);
    horn.position.set(sx * 0.14, 1.86, 0);
    horn.rotation.z = sx * 0.5;
    g.add(horn);
  }
  // mask
  const mask = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), dark);
  mask.position.set(0, 1.6, 0.16);
  mask.scale.z = 0.5;
  g.add(mask);
  return g;
}

function ornamentMesh(matId, quality, supernatural) {
  const g = new THREE.Group();
  const steel = steelMat(matId, supernatural, quality);
  const shape = new THREE.Shape();
  shape.absarc(0, 0, 0.28, 0, Math.PI * 2, false);
  for (const [a, r] of [[0.4, 0.08], [2.4, 0.07], [4.3, 0.09]]) {
    const hole = new THREE.Path();
    hole.absarc(Math.cos(a) * 0.12, Math.sin(a) * 0.12, r, 0, Math.PI * 2, true);
    shape.holes.push(hole);
  }
  const disc = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, { depth: 0.035, bevelEnabled: true, bevelSize: 0.01, bevelThickness: 0.008, bevelSegments: 1 }), steel);
  disc.rotation.x = -Math.PI / 2;
  disc.position.y = 0.72;
  g.add(disc);
  const stand = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.05, 0.3), woodMat(0x32241a));
  stand.position.y = 0.025;
  g.add(stand);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.03, 0.65, 6), woodMat(0x32241a));
  post.position.y = 0.36;
  g.add(post);
  return g;
}

export function createWeaponMesh(typeId, opts = {}) {
  const type = WEAPON_TYPES[typeId] || WEAPON_TYPES.katana;
  const matId = opts.material || 'iron';
  const quality = opts.quality ?? 60;
  const supernatural = !!(opts.supernatural ?? type.supernatural);
  let g;
  switch (typeId) {
    case 'tanto': g = katanaLike({ bladeLen: 0.95, width: 0.07, curve: 0.06, handleLen: 0.34, matId, quality, supernatural }); break;
    case 'wakizashi': g = katanaLike({ bladeLen: 1.45, width: 0.075, curve: 0.12, handleLen: 0.4, matId, quality, supernatural }); break;
    case 'nodachi': g = katanaLike({ bladeLen: 3.1, width: 0.095, curve: 0.28, handleLen: 0.66, matId, quality, supernatural, guard: 'square' }); break;
    case 'kunai': g = kunaiMesh(matId, quality, supernatural); break;
    case 'sai': g = saiMesh(matId, quality, supernatural); break;
    case 'yari': g = poleArm('yari', matId, quality, supernatural); break;
    case 'naginata': g = poleArm('naginata', matId, quality, supernatural); break;
    case 'yumi': g = bowMesh(matId, quality, supernatural); break;
    case 'armour': g = armourMesh(matId, quality, supernatural); break;
    case 'ornament': g = ornamentMesh(matId, quality, supernatural); break;
    case 'oniBlade': g = katanaLike({ bladeLen: 2.3, width: 0.085, curve: 0.24, handleLen: 0.48, matId: 'onisteel', quality, supernatural: true }); break;
    case 'moonBow': g = bowMesh('spiritwood', quality, true); break;
    case 'soulNaginata': g = poleArm('naginata', 'onisteel', quality, true); break;
    default: g = katanaLike({ bladeLen: 2.1, width: 0.08, curve: 0.19, handleLen: 0.46, matId, quality, supernatural });
  }
  g.userData.typeId = typeId;
  g.traverse((o) => { if (o.isMesh) { o.castShadow = true; } });
  return g;
}

export function createWeaponDisplay(weapon, opts = {}) {
  const holder = new THREE.Group();
  const w = createWeaponMesh(weapon.type, { material: weapon.material, quality: weapon.quality, supernatural: weapon.supernatural });
  const isPole = ['naginata', 'yari', 'yumi', 'nodachi'].includes(weapon.type);
  const box = new THREE.Box3().setFromObject(w);
  const size = new THREE.Vector3(); box.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const target = opts.size || (isPole ? 1.7 : 1.15);
  const s = target / maxDim;
  w.scale.setScalar(s);

  if (weapon.type === 'armour') {
    w.position.y = 0;
    holder.add(w);
    return holder;
  }

  // display stand
  const wood = woodMat(0x3a2a1c);
  const base = new THREE.Mesh(new THREE.BoxGeometry(Math.max(0.9, size.x * s * 1.1), 0.07, 0.36), wood);
  base.position.y = 0.035;
  base.castShadow = true;
  holder.add(base);
  for (const sx of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.035, 0.42, 6), wood);
    post.position.set(sx * 0.36, 0.25, 0);
    holder.add(post);
  }
  const rest = new THREE.Mesh(new THREE.BoxGeometry(0.82, 0.05, 0.07), wood);
  rest.position.y = 0.46;
  holder.add(rest);

  w.rotation.z = Math.PI / 2;
  w.rotation.y = 0;
  w.position.set(0, 0.54, 0.02);
  // re-center after rotation
  const box2 = new THREE.Box3().setFromObject(w);
  const center = new THREE.Vector3(); box2.getCenter(center);
  w.position.x -= center.x;
  w.position.y += 0.46 - box2.min.y;

  holder.add(w);
  return holder;
}

export function createWeaponUpright(weapon, opts = {}) {
  const holder = new THREE.Group();
  const w = createWeaponMesh(weapon.type, { material: weapon.material, quality: weapon.quality, supernatural: weapon.supernatural });
  const box = new THREE.Box3().setFromObject(w);
  const size = new THREE.Vector3(); box.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const target = opts.size || 2.2;
  w.scale.setScalar(target / maxDim);
  const box2 = new THREE.Box3().setFromObject(w);
  w.position.y -= box2.min.y;
  holder.add(w);
  return holder;
}

// Procedural Japanese-inspired ambience & SFX — no external audio assets.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.musicOn = true;
    this.soundOn = true;
    this.timer = null;
    this.mood = 'estate';
    this.noteIndex = 0;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.75;
    this.master.connect(this.ctx.destination);

    this.comp = this.ctx.createDynamicsCompressor();
    this.comp.threshold.value = -18;
    this.comp.ratio.value = 3;
    this.comp.connect(this.master);

    this.reverb = this.ctx.createConvolver();
    this.reverb.buffer = this.makeImpulse(3.4, 2.4);
    this.reverbGain = this.ctx.createGain();
    this.reverbGain.gain.value = 0.28;
    this.reverb.connect(this.reverbGain);
    this.reverbGain.connect(this.comp);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.34;
    this.musicGain.connect(this.comp);
    this.musicGain.connect(this.reverb);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.5;
    this.sfxGain.connect(this.comp);

    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.18;
    this.ambientGain.connect(this.comp);

    this.wind = this.makeNoiseSource();
    this.windFilter = this.ctx.createBiquadFilter();
    this.windFilter.type = 'lowpass';
    this.windFilter.frequency.value = 480;
    this.windFilter.Q.value = 0.6;
    this.windGain = this.ctx.createGain();
    this.windGain.gain.value = 0.5;
    this.wind.connect(this.windFilter);
    this.windFilter.connect(this.windGain);
    this.windGain.connect(this.ambientGain);

    // slow LFO on wind
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.06;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 0.22;
    lfo.connect(lfoGain);
    lfoGain.connect(this.windGain.gain);
    lfo.start();

    this.crowd = this.makeNoiseSource();
    this.crowdFilter = this.ctx.createBiquadFilter();
    this.crowdFilter.type = 'bandpass';
    this.crowdFilter.frequency.value = 500;
    this.crowdFilter.Q.value = 0.8;
    this.crowdGain = this.ctx.createGain();
    this.crowdGain.gain.value = 0;
    this.crowd.connect(this.crowdFilter);
    this.crowdFilter.connect(this.crowdGain);
    this.crowdGain.connect(this.ambientGain);

    this.drone = this.ctx.createOscillator();
    this.drone.type = 'sine';
    this.drone.frequency.value = 55;
    this.droneGain = this.ctx.createGain();
    this.droneGain.gain.value = 0;
    this.drone.connect(this.droneGain);
    this.droneGain.connect(this.reverb);
    this.droneGain.connect(this.comp);
    this.drone.start();

    this.ready = true;
    this.startMusic();
  }

  makeImpulse(duration, decay) {
    const rate = this.ctx.sampleRate;
    const len = rate * duration;
    const buf = this.ctx.createBuffer(2, len, rate);
    for (let c = 0; c < 2; c++) {
      const data = buf.getChannelData(c);
      for (let i = 0; i < len; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
      }
    }
    return buf;
  }

  makeNoiseSource() {
    const rate = this.ctx.sampleRate;
    const len = rate * 4;
    const buf = this.ctx.createBuffer(2, len, rate);
    for (let c = 0; c < 2; c++) {
      const d = buf.getChannelData(c);
      let last = 0;
      for (let i = 0; i < len; i++) {
        const white = Math.random() * 2 - 1;
        last = (last + 0.02 * white) / 1.02;
        d[i] = last * 3.2;
      }
    }
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    src.start();
    return src;
  }

  // pentatonic hirajoshi-ish scale (D, Eb, G, A, Bb)
  scale() {
    const root = this.mood === 'oni' ? 146.83 / 2 : 146.83;
    return [1, 1.0595, 1.3348, 1.4983, 1.5874, 2, 2.119, 2.6697, 2.9966, 3.1748];
  }

  startMusic() {
    if (this.timer) clearInterval(this.timer);
    this.timer = setInterval(() => {
      if (!this.ready || !this.musicOn) return;
      const t = this.ctx.currentTime;
      const scale = this.scale();
      const octave = Math.random() > 0.7 ? 2 : 1;
      const n = scale[Math.floor(Math.random() * scale.length)] * 146.83 * octave;
      this.pluck(n, t + 0.02, 0.04 + Math.random() * 0.05, 0.5 + Math.random() * 0.5);
      if (Math.random() > 0.55) {
        this.pluck(n * 1.5, t + 0.18 + Math.random() * 0.25, 0.025, 0.32);
      }
      if (Math.random() > 0.82) {
        this.pluck(n / 2, t + 0.5, 0.03, 0.5);
      }
      if (Math.random() > 0.9) {
        this.flute(n * 2, t + 0.6, 1.8, 0.018);
      }
      if (Math.random() > 0.94) {
        this.bell(n * 2, t + 0.3, 0.02);
      }
    }, 3600);
  }

  pluck(freq, when, vol = 0.04, dur = 0.8) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const out = ctx.createGain();
    out.gain.setValueAtTime(0, when);
    out.gain.linearRampToValueAtTime(vol, when + 0.008);
    out.gain.exponentialRampToValueAtTime(0.0001, when + dur * 2.4);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(3400, when);
    filter.frequency.exponentialRampToValueAtTime(500, when + dur * 1.4);
    filter.Q.value = 2.5;
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    for (const [type, gain, detune] of [['triangle', 1, 0], ['sawtooth', 0.18, 4]]) {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.value = freq * (1 + detune / 1200);
      const g = ctx.createGain();
      g.gain.value = gain;
      o.connect(g);
      g.connect(filter);
      o.start(when);
      o.stop(when + dur * 2.6);
    }
    filter.connect(out);
    if (pan) { pan.pan.value = (Math.random() - 0.5) * 0.8; out.connect(pan); pan.connect(this.musicGain); }
    else out.connect(this.musicGain);
  }

  flute(freq, when, dur = 1.5, vol = 0.02) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(freq, when);
    o.frequency.linearRampToValueAtTime(freq * 1.008, when + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, when);
    g.gain.linearRampToValueAtTime(vol, when + 0.35);
    g.gain.setValueAtTime(vol, when + dur * 0.6);
    g.gain.exponentialRampToValueAtTime(0.0001, when + dur);
    const vib = ctx.createOscillator();
    vib.frequency.value = 5.2;
    const vibG = ctx.createGain();
    vibG.gain.value = freq * 0.006;
    vib.connect(vibG); vibG.connect(o.frequency);
    o.connect(g); g.connect(this.musicGain);
    o.start(when); vib.start(when);
    o.stop(when + dur + 0.1); vib.stop(when + dur + 0.1);
  }

  bell(freq, when, vol = 0.03) {
    if (!this.ready) return;
    const ctx = this.ctx;
    [1, 2.4, 3.8, 5.2].forEach((h, i) => {
      const o = ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = freq * h;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, when);
      g.gain.linearRampToValueAtTime(vol / (i + 1), when + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0001, when + 3 - i * 0.4);
      o.connect(g); g.connect(this.musicGain);
      o.start(when); o.stop(when + 3);
    });
  }

  chord() {
    if (!this.ready) return;
    const t = this.ctx.currentTime + 0.05;
    const base = this.scale()[0] * 146.83;
    [1, 1.3348, 1.4983, 2].forEach((r, i) => {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = base * r;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.012, t + 1.5);
      g.gain.linearRampToValueAtTime(0.0001, t + 6);
      o.connect(g); g.connect(this.reverb); g.connect(this.musicGain);
      o.start(t); o.stop(t + 6.2);
    });
  }

  sfx(type) {
    if (!this.ready || !this.soundOn) return;
    const t = this.ctx.currentTime;
    if (type === 'click') {
      this.blip(880, 0.04, 0.05, 'sine', t);
    } else if (type === 'coin') {
      this.blip(1180, 0.18, 0.11, 'triangle', t);
      this.blip(1560, 0.22, 0.09, 'triangle', t + 0.07);
      this.blip(2100, 0.26, 0.05, 'sine', t + 0.13);
    } else if (type === 'hammer') {
      this.noiseHit(t, 0.12, 0.55, 900);
      this.blip(160, 0.16, 0.15, 'square', t);
      this.bell(520, t, 0.012);
    } else if (type === 'anvil') {
      this.noiseHit(t, 0.06, 0.4, 2600);
      this.blip(740, 0.9, 0.07, 'sine', t);
      this.blip(1130, 0.7, 0.04, 'sine', t);
    } else if (type === 'water') {
      this.noiseHit(t, 0.5, 0.18, 1600);
    } else if (type === 'gavel') {
      this.noiseHit(t, 0.08, 0.7, 700);
      this.blip(120, 0.3, 0.2, 'square', t);
    } else if (type === 'success') {
      [523, 659, 784, 1046].forEach((f, i) => this.bell(f, t + i * 0.09, 0.035));
    } else if (type === 'error') {
      this.blip(180, 0.2, 0.09, 'square', t);
      this.blip(150, 0.25, 0.07, 'square', t + 0.08);
    } else if (type === 'sale') {
      [523, 784, 1046, 1318].forEach((f, i) => this.pluck(f, t + i * 0.1, 0.09, 0.8));
      this.sfx('coin');
    } else if (type === 'oni') {
      this.bell(110, t, 0.05);
      this.bell(164, t + 0.4, 0.03);
      this.noiseHit(t, 2.2, 0.12, 220);
    } else if (type === 'open') {
      this.noiseHit(t, 0.25, 0.08, 1200);
    }
  }

  blip(freq, dur, vol, type, when) {
    const o = this.ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, when);
    g.gain.exponentialRampToValueAtTime(0.0001, when + dur);
    o.connect(g); g.connect(this.sfxGain);
    o.start(when); o.stop(when + dur + 0.02);
  }

  noiseHit(when, dur, vol, freq) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * dur);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.5);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = freq;
    f.Q.value = 1.2;
    const g = ctx.createGain();
    g.gain.value = vol;
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(when);
  }

  setMusic(on) {
    this.musicOn = on;
    if (this.musicGain) this.musicGain.gain.setTargetAtTime(on ? 0.32 : 0, this.ctx.currentTime, 0.3);
  }

  setMood(mood) {
    this.mood = mood;
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    if (mood === 'oni') {
      this.droneGain.gain.setTargetAtTime(0.06, t, 1.5);
      this.crowdGain.gain.setTargetAtTime(0.02, t, 1.5);
      this.windFilter.frequency.setTargetAtTime(260, t, 2);
    } else if (mood === 'auction') {
      this.droneGain.gain.setTargetAtTime(0.012, t, 1.5);
      this.crowdGain.gain.setTargetAtTime(0.09, t, 1.5);
      this.windFilter.frequency.setTargetAtTime(700, t, 2);
    } else {
      this.droneGain.gain.setTargetAtTime(0, t, 1.5);
      this.crowdGain.gain.setTargetAtTime(0, t, 1.5);
      this.windFilter.frequency.setTargetAtTime(480, t, 2);
    }
  }

  setWeather(weather, night) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const rainy = weather === 'rain' || weather === 'storm';
    this.windGain.gain.setTargetAtTime(rainy ? 1.1 : night ? 0.35 : 0.5, t, 2);
    this.windFilter.frequency.setTargetAtTime(rainy ? 2400 : night ? 320 : 520, t, 2);
  }
}

