    }
    for (let i = 0; i < 40; i++) {
      ctx.fillStyle = `rgba(120,100,60,${0.04 + Math.random() * 0.07})`;
      ctx.beginPath(); ctx.arc(Math.random() * w, Math.random() * h, 10 + Math.random() * 30, 0, Math.PI * 2); ctx.fill();
    }
  }, [26, 26]);
}

function stoneTexture() {
