    const slotXs = [-7.2, -5.15, -3.1, -1.05, 1.0, 3.05, 5.1, 7.15];
    for (let row = 0; row < 2; row++) {
      const z = 0.4 + row * 4.0;
      const bench = this.makeBench(17.5, 1.15, 1.2);
