      roof.castShadow = true;
      g.add(roof);
      const trim = new THREE.Mesh(new THREE.BoxGeometry(w + 1.4, 0.12, w + 1.4), MAT.darkWood());
      trim.position.y = y + 1.5;
      g.add(trim);
      y += 2.1;
    }
    const spire = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.1, 2.6, 6), MAT.gold());
